@block ALCtrl begin
    # 1 kHz outer controller of the ACTILINK rotary double pendulum (EtherCAT master, CST mode).
    # Generated by design/actilink_build.py from design/actilink_design.json.
    #
    # Measurement: q0m the arm angle from the drive's 20-bit output encoder; m1*, m2* the AS5048
    # registers of the two passive joints for the SPI chain (a) and the I2C chain (b), `bus` picks
    # the chain. Each register minus its calibration offset (z: the reading at the hanging rest,
    # minus pi for link 1) is unwrapped against the last angle (wrap to +-pi of the increment).
    # Estimator: per joint an alpha-beta-gamma filter, the steady-state Kalman filter of a white-
    # jerk kinematic model (gains G[j, :] = angle, rate, acceleration), predict then correct.
    #
    #   mode 0  t < t_on                  torque 0
    #   mode 1  swing-up                  tau = tau*(t) - K(t) (x - x*(t)), the TVLQR table Tab
    #                                     (rows every dt_tab: x*, tau*, K), linear interpolation
    #   mode 2  balance (latched)         tau = -K x - K7 tau_prev, the discrete LQR designed with
    #                                     the one-cycle EtherCAT delay as a state
    #
    # The switch to mode 2 happens once: at t_on with balance_only = 1, else when t - t_on >= t_s
    # and the weighted norm sqrt(sum cw x^2) is below catch_tol. tau is clamped to +-umax, and with
    # n_delay = 1 the command computed in a cycle is sent in the next one.
    @constants NT::Int = 301
    @inputs begin
        q0m::Real, [unit = "rad", description = "Arm angle (output encoder)"]
        m1a::Real, [unit = "rad", description = "Register, link 1, AS5048A (SPI)"]
        m2a::Real, [unit = "rad", description = "Register, link 2, AS5048A (SPI)"]
        m1b::Real, [unit = "rad", description = "Register, link 1, AS5048B (I2C)"]
        m2b::Real, [unit = "rad", description = "Register, link 2, AS5048B (I2C)"]
        tm::Real, [unit = "s"]
    end
    @outputs begin
        tau::Real = 0.0, [unit = "N*m", description = "Target torque sent to the drive"]
        mode::Real = 0.0, [description = "0 idle, 1 swing-up, 2 balance"]
        q1e::Real = 0.0, [unit = "rad", description = "Estimated joint 1 angle"]
        q2e::Real = 0.0, [unit = "rad", description = "Estimated joint 2 angle"]
        q3e::Real = 0.0, [unit = "rad", description = "Estimated joint 3 angle"]
        w1e::Real = 0.0, [unit = "rad/s", description = "Estimated joint 1 rate"]
        w2e::Real = 0.0, [unit = "rad/s", description = "Estimated joint 2 rate"]
        w3e::Real = 0.0, [unit = "rad/s", description = "Estimated joint 3 rate"]
        th1::Real = 0.0, [unit = "rad", description = "Measured link 1 angle (unwrapped)"]
        th2::Real = 0.0, [unit = "rad", description = "Measured link 2 angle (unwrapped)"]
        enorm::Real = 0.0, [description = "Catch norm"]
    end
