        ulq = -(K[1] * a1 + K[2] * a2 + K[3] * a3 + K[4] * v1 + K[5] * v2 + K[6] * v3 + K[7] * up)
        en = sqrt(cw[1] * a1 * a1 + cw[2] * a2 * a2 + cw[3] * a3 * a3 + cw[4] * v1 * v1 + cw[5] * v2 * v2 + cw[6] * v3 * v3)
        if tm >= t_on && (balance_only > 0.5 || (tau_on >= t_s && en < catch_tol))
            latched = 1.0
        end
        u = ifelse(tm < t_on, 0.0, ifelse(latched > 0.5, ulq, utv))
        u = clamp(u, -umax, umax)
        tau = ifelse(n_delay > 0.5, up, u)
        up = u
        mode = ifelse(tm < t_on, 0.0, ifelse(latched > 0.5, 2.0, 1.0))
        q1e = a1
        w1e = v1
        q2e = a2
        w2e = v2
        q3e = a3
        w3e = v3
        th1 = u1
        th2 = u2
        enorm = en
    end
end
